with DATASET_PATH.open("r", encoding="utf-8") as f:
    data = json.load(f)

existing_ids = {item["id"] for item in data}
duplicates = [item["id"] for item in NEW_EXAMPLES if item["id"] in existing_ids]

if duplicates:
    raise ValueError(f"Duplicate IDs already exist: {duplicates}")

data.extend(NEW_EXAMPLES)

with DATASET_PATH.open("w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)
    f.write("\n")

print(f"Added {len(NEW_EXAMPLES)} V11 hard-negative examples.")
print(f"Total examples: {len(data)}")
